begin;set local role postgres;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions,pgtap;select plan(72);
select ok(exists(select 1 from information_schema.columns where table_schema='public'and table_name='erp_establishments'and column_name='state_registration'),'state registration exists');
select ok(exists(select 1 from pg_constraint where conname='erp_establishments_state_registration_format'),'state registration constrained');
select ok(to_regclass('public.tenants_domain_unique')is not null,'tenant domain unique index exists');
select ok(to_regclass('public.erp_auth_invitation_outbox')is not null,'auth invitation outbox exists');
select ok(to_regclass('public.erp_auth_identity_compensations')is not null,'auth compensation table exists');
select ok((select relrowsecurity from pg_class where oid='public.erp_auth_invitation_outbox'::regclass),'outbox RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.erp_auth_identity_compensations'::regclass),'compensation RLS enabled');
select ok(not has_table_privilege(role_name,'public.'||table_name,privilege),format('%s cannot %s %s',role_name,privilege,table_name))from(values('anon','erp_auth_invitation_outbox','SELECT'),('anon','erp_auth_invitation_outbox','INSERT'),('authenticated','erp_auth_invitation_outbox','SELECT'),('authenticated','erp_auth_invitation_outbox','INSERT'),('anon','erp_auth_identity_compensations','SELECT'),('anon','erp_auth_identity_compensations','INSERT'),('authenticated','erp_auth_identity_compensations','SELECT'),('authenticated','erp_auth_identity_compensations','INSERT'))v(role_name,table_name,privilege);
select ok(exists(select 1 from information_schema.columns where table_schema='public'and table_name='erp_auth_invitation_outbox'and column_name=n),format('outbox column %s exists',n))from unnest(array['id','run_id','tenant_id','subject_key','email_ref','payload_hash','status','auth_user_id','attempt_count','lease_until','last_error_code','created_at','updated_at'])n;
select ok(exists(select 1 from information_schema.columns where table_schema='public'and table_name='erp_auth_identity_compensations'and column_name=n),format('compensation column %s exists',n))from unnest(array['id','run_id','outbox_id','tenant_id','auth_user_id','action','status','reason_hash','created_at','finished_at'])n;
select ok(to_regprocedure(signature)is not null,format('%s exists',signature))from unnest(array['public.erp_prepare_pilot_provisioning_v1(jsonb)','public.erp_record_pilot_auth_identity_v1(uuid,uuid)','public.erp_finalize_pilot_identity_v1(uuid,uuid)','public.erp_schedule_pilot_auth_compensation_v1(uuid,text)'])signature;
select ok(p.prosecdef,format('%s security definer',p.proname))from pg_proc p where p.oid=any(array['public.erp_prepare_pilot_provisioning_v1(jsonb)'::regprocedure,'public.erp_record_pilot_auth_identity_v1(uuid,uuid)'::regprocedure,'public.erp_finalize_pilot_identity_v1(uuid,uuid)'::regprocedure,'public.erp_schedule_pilot_auth_compensation_v1(uuid,text)'::regprocedure])order by p.proname;
select ok(exists(select 1 from unnest(p.proconfig)c where c like'search_path=%'and c not like'%public%'),format('%s has empty search path',p.proname))from pg_proc p where p.oid=any(array['public.erp_prepare_pilot_provisioning_v1(jsonb)'::regprocedure,'public.erp_record_pilot_auth_identity_v1(uuid,uuid)'::regprocedure,'public.erp_finalize_pilot_identity_v1(uuid,uuid)'::regprocedure,'public.erp_schedule_pilot_auth_compensation_v1(uuid,text)'::regprocedure])order by p.proname;
select ok(not has_function_privilege('anon',signature,'EXECUTE'),format('anon cannot execute %s',signature))from unnest(array['public.erp_prepare_pilot_provisioning_v1(jsonb)','public.erp_record_pilot_auth_identity_v1(uuid,uuid)','public.erp_finalize_pilot_identity_v1(uuid,uuid)','public.erp_schedule_pilot_auth_compensation_v1(uuid,text)'])signature;
select ok(not has_function_privilege('authenticated',signature,'EXECUTE'),format('authenticated cannot execute %s',signature))from unnest(array['public.erp_prepare_pilot_provisioning_v1(jsonb)','public.erp_record_pilot_auth_identity_v1(uuid,uuid)','public.erp_finalize_pilot_identity_v1(uuid,uuid)','public.erp_schedule_pilot_auth_compensation_v1(uuid,text)'])signature;
select ok(has_function_privilege('service_role',signature,'EXECUTE'),format('service role executes %s',signature))from unnest(array['public.erp_prepare_pilot_provisioning_v1(jsonb)','public.erp_record_pilot_auth_identity_v1(uuid,uuid)','public.erp_finalize_pilot_identity_v1(uuid,uuid)','public.erp_schedule_pilot_auth_compensation_v1(uuid,text)'])signature;
select ok(pg_get_functiondef('public.erp_prepare_pilot_provisioning_v1(jsonb)'::regprocedure)like'%pg_advisory_xact_lock%','prepare serializes idempotency');
select ok(pg_get_functiondef('public.erp_prepare_pilot_provisioning_v1(jsonb)'::regprocedure)like'%idempotency conflict%','prepare rejects divergent replay');
select ok(pg_get_functiondef('public.erp_prepare_pilot_provisioning_v1(jsonb)'::regprocedure)like'%unsafe provisioning request%','prepare rejects secrets and unknown fields');
select ok(pg_get_functiondef('public.erp_prepare_pilot_provisioning_v1(jsonb)'::regprocedure)like'%erp_set_tenant_capability%','prepare uses capability broker RPC');
select ok(pg_get_functiondef('public.erp_prepare_pilot_provisioning_v1(jsonb)'::regprocedure)like'%erp_auth_invitation_outbox%','prepare enqueues invitation atomically');
select ok(pg_get_functiondef('public.erp_record_pilot_auth_identity_v1(uuid,uuid)'::regprocedure)like'%auth.users%','record verifies Auth identity');
select ok(pg_get_functiondef('public.erp_finalize_pilot_identity_v1(uuid,uuid)'::regprocedure)like'%erp_tenant_memberships%','finalize binds membership');
select ok(pg_get_functiondef('public.erp_finalize_pilot_identity_v1(uuid,uuid)'::regprocedure)like'%requires_mfa%','finalize requires privileged MFA role');
select ok(pg_get_functiondef('public.erp_schedule_pilot_auth_compensation_v1(uuid,text)'::regprocedure)like'%erp_auth_identity_compensations%','compensation is durable');
select ok(pg_get_functiondef('public.erp_schedule_pilot_auth_compensation_v1(uuid,text)'::regprocedure)like'%compensation_required%','compensation changes outbox state');
select*from finish();rollback;
